    ev("openChapter('c6b')"); pg.wait_for_timeout(500)
    if pg.locator('#modal').is_visible() and pg.locator('#modal [data-close]').count(): pg.locator('#modal [data-close]').first.click(); pg.wait_for_timeout(200)
